<template><view class="page"><view class="card"><text class="heading">生长对比与环境趋势</text><text class="muted">{{farmName}}</text><view class="buttons"><button size="mini" :class="{active:mode==='growth'}" @click="mode='growth';clear()">两期长势</button><button size="mini" :class="{active:mode==='environment'}" @click="mode='environment';clear()">环境历史</button></view><business-fields :fields="fields" v-model="form" :farm-id="farmId"/><button :disabled="busy" :loading="busy" @click="load">查询</button></view><view v-if="error" class="error">{{error}}</view><template v-if="mode==='growth'&&records.length"><view class="card"><business-fields :fields="recordFields" v-model="selection"/><text class="muted">同地块两期实测记录对比，不根据长势等级估算产量。</text></view><view v-if="a&&b" class="card"><text class="heading">两期对比</text><view class="compare"><text>指标</text><text>前期</text><text>后期</text></view><view v-for="f in comparisonFields" :key="f.key" class="compare"><text>{{f.label}}</text><text>{{a[f.key] ?? '—'}}</text><text>{{b[f.key] ?? '—'}}<text v-if="f.numeric" class="delta">{{delta(f.key)}}</text></text></view><button size="mini" @click="exportCompare">导出对比</button></view><view class="card"><text class="heading">现场照片</text><view v-for="record in photoRecords" :key="record.recordId"><text class="muted">{{record.recordDate}}</text><view class="photos"><image v-for="photo in photos(record)" :key="photo" :src="photo" mode="aspectFill" @click="previewPhoto(photo,record)"/></view><text v-if="!photos(record).length" class="muted">未上传照片</text></view></view></template><template v-if="mode==='environment'&&history"><view class="card"><text class="muted">日均值；缺测保留为空，不补零。原始数据可回环境列表导出。</text><button size="mini" @click="exportHistory">导出每日指标</button><view v-for="metric in metricOptions" :key="metric.value"><template v-if="history.series?.[metric.value]"><text class="heading">{{metric.label}}</text><view v-for="(day,i) in history.dates" :key="day" class="record"><view class="row"><text>{{day}}</text><text>{{history.series[metric.value][i] ?? '缺测'}}</text></view><view class="track"><view v-if="history.series[metric.value][i]!=null" class="bar" :style="{width:barWidth(metric.value,history.series[metric.value][i])+'%'}"/></view><text class="muted">最小 {{stat(metric.value,day,'min')}} · 最大 {{stat(metric.value,day,'max')}} · {{stat(metric.value,day,'count')}} 个样本</text></view></template></view></view></template><view v-if="loaded&&!records.length&&!history" class="card muted">所选范围暂无记录</view></view></template>
<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import {onLoad,onShow,onHide} from '@dcloudio/uni-app'
import {call,plot,reference,date,select,type Row,type Field} from '@/api/native-business'
import {ensureWorkspaceSession,isProductionOps} from '@/utils/workspace'
import {resolveCurrentFarm} from '@/utils/auth-helper'
import {contextGuard,csv,saveText} from '@/utils/business-files'
import BusinessFields from '@/components/business-fields/business-fields.vue'
const mode=ref('growth'),farmId=ref(''),farmName=ref(''),form=ref<Row>({}),selection=ref<Row>({}),records=ref<Row[]>([]),history=ref<Row>(),busy=ref(false),loaded=ref(false),error=ref('');let version=0
const metricOptions=[{value:'air_temperature',label:'气温℃'},{value:'air_humidity',label:'湿度%'},{value:'soil_moisture',label:'土壤水分%'},{value:'soil_temperature',label:'土温℃'},{value:'light_intensity',label:'光照lux'}]
const fields=computed<Field[]>(()=>[plot(),...(mode.value==='environment'?[reference('deviceId','设备','/iot/devices','deviceId','deviceName'),date('startDate','开始日期',true),date('endDate','结束日期',true),{...select('metrics','统计指标',metricOptions,true),multiple:true}]:[])])
const recordFields=computed(()=>['a','b'].map((key,i)=>select(key,i?'后期记录':'前期记录',records.value.map(r=>({value:String(r.recordId),label:(r.recordDate||r.createdAt)+' · '+(r.growthStage||'未填阶段')})),true)))
const a=computed(()=>records.value.find(r=>String(r.recordId)===selection.value.a)),b=computed(()=>records.value.find(r=>String(r.recordId)===selection.value.b))
const photoRecords=computed<Row[]>(()=>[a.value,b.value].filter((r):r is Row=>!!r))
const comparisonFields=[{key:'recordDate',label:'日期'},{key:'growthStage',label:'生育期'},{key:'plantHeight',label:'株高cm',numeric:true},{key:'leafCount',label:'叶片数',numeric:true},{key:'leafAreaIndex',label:'叶面积指数',numeric:true},{key:'pestInfo',label:'病虫情况'}]
function clear(){version++;records.value=[];history.value=undefined;selection.value={};error.value='';loaded.value=false;busy.value=false}
watch(()=>JSON.stringify([form.value,mode.value]),clear)
function delta(key:string){const x=a.value?.[key],y=b.value?.[key];if(x==null||y==null)return '差值缺测';const n=Number(y)-Number(x);return Number.isFinite(n)?(n>=0?'+':'')+Number(n.toFixed(3)):''}
function photos(r:Row){if(Array.isArray(r.photoUrls))return r.photoUrls;if(Array.isArray(r.photos))return r.photos;try{const values=JSON.parse(r.photos||'[]');return Array.isArray(values)?values:[]}catch{return []}}
function previewPhoto(p:string,r:Row){uni.previewImage({current:p,urls:photos(r)})}
const stat=(m:string,d:string,k:string)=>history.value?.stats?.[m]?.[d]?.[k]??'—'
function barWidth(m:string,v:number){const values=(history.value?.series?.[m]||[]).filter((x:any)=>x!=null).map(Number);const min=Math.min(0,...values),max=Math.max(1,...values);return Math.max(0,Math.min(100,(v-min)/(max-min)*100))}
async function initialize(){try{if(!await ensureWorkspaceSession())return;if(isProductionOps())throw new Error('请切换到用户端');const farm=await resolveCurrentFarm();if(!farm)return;farmId.value=String(farm.farmId);farmName.value=farm.farmName||''}catch(e:any){error.value=e.message}}
async function load(){if(busy.value)return;clear();const run=++version;busy.value=true;try{if(!form.value.plotId)throw new Error('请选择地块');if(mode.value==='environment'&&(!form.value.startDate||!form.value.endDate||form.value.startDate>form.value.endDate||!form.value.metrics?.length))throw new Error('请选择有效日期与统计指标');const guard=contextGuard();const raw=await call(mode.value==='growth'?'/growth/by-plot':'/growth/environment/history','GET',undefined,{...form.value,metrics:form.value.metrics?.join(',')});guard();if(run!==version)return;if(mode.value==='growth'){if(!Array.isArray(raw))throw new Error('记录格式异常');records.value=raw.sort((a,b)=>String(a.recordDate).localeCompare(String(b.recordDate)))}else history.value=raw;loaded.value=true}catch(e:any){if(run===version)error.value=e.message}finally{if(run===version)busy.value=false}}
async function exportCompare(){try{if(!a.value||!b.value||a.value.recordId===b.value.recordId)throw new Error('请选择两条不同记录');await saveText('同地块长势对比.csv',csv(comparisonFields.map(f=>({metric:f.label,before:a.value?.[f.key],after:b.value?.[f.key],delta:f.numeric?delta(f.key):''})),[{key:'metric',label:'指标'},{key:'before',label:'前期'},{key:'after',label:'后期'},{key:'delta',label:'差值'}]))}catch(e:any){error.value=e.message}}
async function exportHistory(){try{const rows:Row[]=[];for(const [m,values] of Object.entries(history.value?.series||{}))for(let i=0;i<(values as any[]).length;i++){const day=history.value!.dates[i];rows.push({date:day,metric:metricOptions.find(x=>x.value===m)?.label||m,avg:(values as any[])[i],min:stat(m,day,'min'),max:stat(m,day,'max'),count:stat(m,day,'count')})}await saveText('环境每日统计.csv',csv(rows,[{key:'date',label:'日期'},{key:'metric',label:'指标'},{key:'avg',label:'均值'},{key:'min',label:'最小值'},{key:'max',label:'最大值'},{key:'count',label:'样本数'}]))}catch(e:any){error.value=e.message}}
onLoad(o=>{mode.value=o?.mode==='environment'?'environment':'growth'});onShow(()=>void initialize());onHide(clear)
</script>
<style scoped>.page{padding:24rpx 24rpx calc(40rpx + env(safe-area-inset-bottom));background:#f4f6f2;min-height:100vh;box-sizing:border-box}.card{padding:28rpx;border-radius:18rpx;background:#fff;margin-bottom:24rpx}.heading{display:block;font-size:32rpx;font-weight:600;margin:18rpx 0}.muted{display:block;font-size:24rpx;color:#666666;line-height:1.8;margin:16rpx 0}.buttons{display:flex;gap:16rpx;margin:22rpx 0;flex-wrap:wrap}.buttons button{margin:0;min-height:84rpx;font-size:26rpx}.active{background:#126d43;color:white}.compare{display:grid;grid-template-columns:1fr 1fr 1fr;gap:14rpx;padding:22rpx 0;border-bottom:1rpx solid #e7ece3;font-size:26rpx;word-break:break-all}.delta{display:block;color:#126d43;font-size:24rpx}.photos{display:flex;flex-wrap:wrap;gap:16rpx}.photos image{width:180rpx;height:180rpx;border-radius:12rpx}.row{display:flex;justify-content:space-between;font-size:26rpx;gap:18rpx}.record{padding:16rpx 0}.track{height:12rpx;background:#eff3eb;margin-top:14rpx}.bar{height:100%;background:#27804f}.error{padding:24rpx;background:#fff0e8;color:#a43d28;font-size:26rpx;margin-bottom:24rpx}</style>
